import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const html=fs.readFileSync(new URL('../arcade.html',import.meta.url),'utf8');
const script=html.match(/<script>([\s\S]*?)<\/script>/)[1];
function fixture(storageFails=false){
 const nodes=new Map(),events={};
 const ctx=new Proxy({}, {get:()=>()=>{}});
 function node(id='') {return {id,style:{},dataset:{},classList:{add(){},remove(){}},handlers:{},textContent:'',hidden:false,disabled:false,tagName:'BUTTON',getContext:()=>ctx,setAttribute(){},blur(){},setPointerCapture(){},addEventListener(k,f){(this.handlers[k]??=[]).push(f);},fire(k,e={}){for(const f of this.handlers[k]||[])f(e);},append(n){nodes.set(n.id,n);},remove(){nodes.delete(this.id);}};}
 for(const m of html.matchAll(/id="([^"]+)"/g))nodes.set(m[1],node(m[1]));
 const buttons=['left','right','down','rotate','ccw','hold','drop'].map(action=>{const n=node();n.dataset.action=action;return n;});
 const document={getElementById:id=>nodes.get(id)||null,querySelector:()=>buttons.find(b=>b.dataset.action==='hold'),querySelectorAll:()=>buttons,createElement:()=>node(),addEventListener:(k,f)=>events[k]=f};
 const store={};
 const sandbox={document,window:{addEventListener:(k,f)=>events[k]=f},localStorage:{getItem(k){if(storageFails)throw Error('denied');return store[k];},setItem(k,v){if(storageFails)throw Error('denied');store[k]=v;}},requestAnimationFrame(){},setTimeout:()=>1,clearTimeout(){},setInterval:()=>2,clearInterval(){}};
 vm.createContext(sandbox);vm.runInContext(script,sandbox);
 return {run:code=>vm.runInContext(code,sandbox),nodes,buttons,events,store};
}
test('seven-bag distribution, board dimensions and preview order',()=>{
 const f=fixture();assert.equal(f.run('game.board.length'),20);assert.equal(f.run('game.board.every(r=>r.length===10)'),true);
 assert.equal(f.run('const g=new MoonGame(()=>.4);g.bag=[];new Set(Array.from({length:7},()=>g.take())).size'),7);
 assert.equal(f.run('const next=game.queue[0];game.hardDrop();game.piece.type===next'),true);
});
test('walls, floor and occupied cells stop movement',()=>{
 const f=fixture();f.run("game.spawn('O');while(game.move(-1,0)){};");assert.equal(f.run('game.piece.x'),0);assert.equal(f.run('game.move(-1,0)'),false);
 f.run('while(game.move(0,1)){}');assert.equal(f.run('game.piece.y'),18);assert.equal(f.run('game.move(0,1)'),false);
 assert.equal(f.run("game.board[18][2]='T';game.move(1,0)"),false);
});
test('four rotations restore shape; floor rotation stays legal',()=>{
 const f=fixture();assert.equal(f.run("game.spawn('T');const original=JSON.stringify(game.piece.m);for(let i=0;i<4;i++)game.rotate();JSON.stringify(game.piece.m)===original"),true);
 assert.equal(f.run('game.piece.y=game.ghostY();game.rotate();game.fits(game.piece.m,game.piece.x,game.piece.y)'),true);
});
test('hard drop follows ghost, locks four cells and scores distance',()=>{
 const f=fixture();const distance=f.run('game.ghostY()-game.piece.y');f.run('game.hardDrop()');assert.equal(f.run('game.board.flat().filter(Boolean).length'),4);assert.equal(f.run('game.score'),distance*2);
});
test('one through four rows clear simultaneously with exact awards',()=>{
 for(let n=1;n<=4;n++){
  const f=fixture();f.run(`game.board=Array.from({length:20},()=>Array(10).fill(null));for(let y=20-${n};y<20;y++){game.board[y].fill('T');game.board[y][4]=null;}game.piece={type:'I',m:[[1],[1],[1],[1]],x:4,y:16};game.lock();`);
  assert.equal(f.run('game.lines'),n);assert.equal(f.run('game.score'),[0,100,300,500,800][n]);assert.equal(f.run('game.board.length'),20);assert.equal(f.run('game.board.flat().filter(Boolean).length'),4-n);
 }
});
test('level advances at ten lines and consecutive clears add combo bonus',()=>{
 const f=fixture();f.run("game.lines=9;game.board[19].fill('T');game.board[19][4]=null;game.piece={type:'I',m:[[1]],x:4,y:19};game.lock();");assert.equal(f.run('game.level'),2);assert.equal(f.run('game.score'),100);
 f.run("game.board[19].fill('T');game.board[19][4]=null;game.piece={type:'I',m:[[1]],x:4,y:19};game.lock();");assert.equal(f.run('game.score'),400);
});
test('hold is once per lock and swap preserves queue head',()=>{
 const f=fixture();assert.equal(f.run('const first=game.piece.type;game.hold();game.held===first'),true);assert.equal(f.run('game.hold()'),false);
 f.run('game.hardDrop()');assert.equal(f.run('game.usedHold'),false);assert.equal(f.run('const upcoming=game.queue[0];game.hold();game.piece.type===first&&game.queue[0]===upcoming'),true);
});
test('blocked spawn ends game and restart clears every run field',()=>{
 const f=fixture();f.run("game.board[0].fill('T');game.board[1].fill('T');game.spawn('O');");assert.equal(f.run('game.over'),true);assert.equal(f.run('game.move(1,0)'),false);
 f.run('game.reset()');assert.equal(f.run('game.over||game.usedHold||game.held!==null||game.score!==0||game.lines!==0||game.board.flat().some(Boolean)'),false);
});
test('pause freezes inputs and clock; resume restores falling; blur pauses',()=>{
 const f=fixture();f.run('start();togglePause()');const before=f.run('JSON.stringify(game)');f.run("act('drop');act('hold');for(let i=1;i<40;i++)tick(i*50)");assert.equal(f.run('JSON.stringify(game)'),before);
 f.run('togglePause();for(let i=40;i<80;i++)tick(i*50)');assert.ok(f.run('game.piece.y')>0);f.events.blur();assert.equal(f.run('state'),'paused');
});
test('touch bindings move, hold, drop; game over overlay and replay work',()=>{
 const f=fixture();f.nodes.get('play').fire('click');const x=f.run('game.piece.x');const tap=a=>f.buttons.find(b=>b.dataset.action===a).fire('pointerdown',{preventDefault(){},pointerId:1});tap('left');assert.equal(f.run('game.piece.x'),x-1);tap('hold');assert.equal(f.run('game.usedHold'),true);tap('drop');assert.ok(f.run('game.score')>0);
 f.run("game.board[0].fill('T');game.board[1].fill('T');game.spawn('O');game.lastClear=0;afterLock()");assert.equal(f.run('state'),'over');assert.equal(f.nodes.get('overlay').hidden,false);f.nodes.get('play').fire('click');assert.equal(f.run('state'),'playing');assert.equal(f.run('game.score'),0);
});
test('restart confirmation supports cancel, confirm and repeated restart without stale buttons',()=>{
 const f=fixture();f.run('start();game.score=125');f.nodes.get('restart').fire('click');assert.equal(f.run('state'),'confirm');f.nodes.get('cancelRestart').onclick();assert.equal(f.run('state'),'playing');assert.equal(f.run('game.score'),125);
 f.nodes.get('restart').fire('click');f.nodes.get('restart').fire('click');assert.equal(f.nodes.has('cancelRestart'),false);assert.equal(f.run('game.score'),0);assert.equal(f.store['moonstack.best'],'125');
 f.nodes.get('restart').fire('click');f.nodes.get('play').fire('click');assert.equal(f.run('state'),'playing');assert.equal(f.nodes.has('cancelRestart'),false);
});
test('storage denial is harmless and no remote resources are needed',()=>{
 const f=fixture(true);f.run("start();act('drop');start()");assert.equal(f.run('state'),'playing');assert.doesNotMatch(html,/<(?:script|link|img|audio|video)[^>]+(?:src|href)\s*=/i);assert.doesNotMatch(script,/\b(?:fetch|XMLHttpRequest|WebSocket)\s*\(/);
});

