import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const file=new URL('../arcade.html',import.meta.url);
test('deliver one regular, bounded HTML file',()=>{
 const s=fs.lstatSync(file);assert.ok(s.isFile()&&!s.isSymbolicLink());assert.ok(s.size>0&&s.size<=1024*1024);
 const text=fs.readFileSync(file,'utf8');assert.match(text,/<!doctype html>/i);assert.match(text,/<html\b/i);assert.match(text,/<title>[^<]+<\/title>/i);assert.match(text,/name=["']viewport["']/i);
});
test('include classic JavaScript that parses',()=>{
 const text=fs.readFileSync(file,'utf8');const blocks=[...text.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi)];
 assert.ok(blocks.length>0);for(const [,attrs,code] of blocks){assert.doesNotMatch(attrs,/\bsrc\s*=/i);assert.doesNotMatch(attrs,/type\s*=\s*["']module["']/i);new vm.Script(code);}
});

